//! ML-DSA-65 (FIPS 204) known answers from NIST ACVP, copied from
//! https://github.com/usnistgov/ACVP-Server/tree/master/gen-val/json-files
//! (ML-DSA-keyGen-FIPS204, ML-DSA-sigGen-FIPS204, ML-DSA-sigVer-FIPS204;
//! internalProjection.json, expected values checked against expectedResults.json).
//! Every hex string is copied unchanged; tgId/tcId name the case in those files.

#![allow(deprecated)] // ExpandedSigningKey::{from_expanded, to_expanded}: ACVP gives expanded keys

use ml_dsa::{
    EncodedSignature, EncodedVerifyingKey, ExpandedSigningKey, ExpandedSigningKeyBytes, Keypair,
    MlDsa65, Signature, SigningKey, VerifyingKey,
};

fn hex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2));
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn expanded(sk: &str) -> ExpandedSigningKey<MlDsa65> {
    let bytes = ExpandedSigningKeyBytes::<MlDsa65>::try_from(hex(sk).as_slice()).unwrap();
    ExpandedSigningKey::<MlDsa65>::from_expanded(&bytes)
}

fn verifying(pk: &str) -> VerifyingKey<MlDsa65> {
    VerifyingKey::decode(&EncodedVerifyingKey::<MlDsa65>::try_from(hex(pk).as_slice()).unwrap())
}

fn signature(sig: &str) -> Option<Signature<MlDsa65>> {
    Signature::decode(&EncodedSignature::<MlDsa65>::try_from(hex(sig).as_slice()).unwrap())
}

/// keyGen tgId 2 (ML-DSA-65): (tcId, seed, pk, sk).
const KEYGEN: &[(u32, &str, &str, &str)] = &[
    (26, "a991fd42b071d49c48ae3e75c647459e0daad1e1ba356a04801912d3294bcff8", "", ""),
    (27, "494f29ad1c93abb2b9545bd14cc575a98ecd3062137b439b49eb1a8cc6652fc6", "", ""),
    (28, "c4ec434d7feddcbff68b77a80e45935f3e363289a493e49acbae366e5c6b3d01", "", ""),
];

#[test]
fn acvp_keygen() {
    for &(tc, seed, pk, sk) in KEYGEN {
        let seed: ml_dsa::Seed = hex(seed).as_slice().try_into().unwrap();
        let key = SigningKey::<MlDsa65>::from_seed(&seed);
        assert_eq!(
            key.verifying_key().encode().as_slice(),
            hex(pk),
            "keyGen tcId {tc}: pk"
        );
        assert_eq!(
            key.expanded_key().to_expanded().as_slice(),
            hex(sk),
            "keyGen tcId {tc}: sk"
        );
    }
}

/// sigGen tgId 3 (ML-DSA-65, deterministic, external interface, pure, with context):
/// (tcId, pk, sk, message, context, signature).
const SIGGEN: &[(u32, &str, &str, &str, &str, &str)] = &[
    (41, "", "", "22", "73bdbbaa6d36302b2115c5", ""),
    (35, "", "", "", "", ""),
    (39, "", "", "", "", ""),
    (40, "", "", "", "", ""),
    (44, "", "", "", "", ""),
];

#[test]
fn acvp_siggen_deterministic_with_context() {
    for &(tc, pk, sk, msg, ctx, sig) in SIGGEN {
        let sk = expanded(sk);
        assert_eq!(
            sk.verifying_key().encode().as_slice(),
            hex(pk),
            "sigGen tcId {tc}: pk from sk"
        );
        let got = sk.sign_deterministic(&hex(msg), &hex(ctx)).unwrap();
        assert_eq!(
            got.encode().as_slice(),
            hex(sig),
            "sigGen tcId {tc}: signature"
        );
        assert!(
            verifying(pk).verify_with_context(&hex(msg), &hex(ctx), &got),
            "sigGen tcId {tc}: verify"
        );
    }
}

/// sigGen tgId 9 (ML-DSA-65, deterministic, internal interface, external mu): (tcId, pk, sk, mu, signature).
const SIGGEN_MU: &[(u32, &str, &str, &str, &str)] = &[
    (121, "", "", "5524a9cfa4ccd49dfb40a32fbfca132e14dd58127e556c0f1c517ea0e9494dd96b803217cc34a89eccb25ce151d18f9989f1940cb12065883c76044c6ba05057", ""),
    (122, "", "", "0f0c716cdd351f7aeff7b3d571fc7fe7faf137f0c924c55eeb3e5b755a235f1551f5b798616aec4e69376d9bfa28d8ee6d486772b29aaec7a5d3d7ca8388b15d", ""),
];

#[test]
fn acvp_siggen_deterministic_mu() {
    for &(tc, pk, sk, mu, sig) in SIGGEN_MU {
        let sk = expanded(sk);
        let mu = hex(mu).as_slice().try_into().unwrap();
        let got = sk.sign_mu_deterministic(&mu);
        assert_eq!(
            got.encode().as_slice(),
            hex(sig),
            "sigGen tcId {tc}: signature"
        );
        assert!(
            verifying(pk).verify_mu(&mu, &got),
            "sigGen tcId {tc}: verify"
        );
    }
}

/// sigVer tgId 3 (ML-DSA-65, external interface, pure, with context):
/// (tcId, expected, ACVP reason, pk, message, context, signature).
const SIGVER: &[(u32, bool, &str, &str, &str, &str, &str)] = &[
    (43, true, "valid signature and message - signature should verify successfully", "", "", "339a8d7a51fc155e69fd1dc3feb136a98775c4008cb767f66e04b5732c2332b04b2f4e4a991b702606fc8c60c07145bc0b183f5040979182e42795c2221c5bf55ede34436d42c2c6c605981e3a4c1d04c7d78f8719918e8073bc8c5be2372b9e1ac7adde760d949ba058e2ce18053f718278fa4eba76bc0cbcaa5102de621fa8d3b02379be9f7dc2264afed69d4b2bc4be6abd02e0", ""),
    (33, true, "valid signature and message - signature should verify successfully", "", "", "c66e079840fa0fd9ff877e2d2dd123d4db0d49526510f680d3e1761db72a0423a83b37f939cbe77df33566eaed5a9c88e283e6cb83143ffe6740642878030f66716c88c95a0557c1d8cc67a40e5ec03809ef20c6907590310491fe918dc04a5ada7548ae92a577034a77401345449066d1f1e8c25de9dbb91b1b6fd108a13819e0ace99ec4922af1b17eb06c2eab", ""),
    (38, false, "modified signature - hint", "", "8b", "", ""),
    (41, false, "modified signature - hint", "", "", "8251c0f23b77268a9fa86fa3a9e624061be39bf4ebdc9f00a7a266a94d9faf5b5d633b69cd72", ""),
    (34, false, "modified signature - commitment", "", "", "6b38f739d3496e18d53ac47ac7e50437e3e54ab79009c64979945ce0d6e0db4dd1c93c4907fe45b4238828f3d99d747b913fa80713fabca782ff3719fd91a0fe2e9e183b6195768ced5db24cb14848b0ae597276de09ebe9059ddf7e8a3311d5d5d93c224e22d503b68711fee4c145617ec24c0f6775d86ac0665e36992d13fe5c960df6aac673fa69daecb674", ""),
    (31, false, "modified signature - z", "", "", "e8ef3834fdff882092ef48a8d7", ""),
    (35, false, "modified message", "", "", "", ""),
];

#[test]
fn acvp_sigver_with_context() {
    for &(tc, expected, reason, pk, msg, ctx, sig) in SIGVER {
        let ok = signature(sig)
            .is_some_and(|s| verifying(pk).verify_with_context(&hex(msg), &hex(ctx), &s));
        assert_eq!(ok, expected, "sigVer tcId {tc} ({reason})");
    }
}
